        [ "Right of withdrawal", "Consumers have a 14-day right to withdraw from distance contracts with professional sellers from receipt, without giving a reason. You may notify the seller via the platform, by email or using the model form, and must return the goods within 14 days of withdrawal." ],
        [ "Exceptions", "There is no withdrawal right, among others, for sealed goods unsealed after delivery that cannot be returned for hygiene or data protection reasons, or for goods made to your specification." ],
        [ "Model withdrawal form", "<p>You may use this model:</p><blockquote><p>To [seller], [address]. I hereby withdraw from the contract for the following goods: [description], ordered on [date] and received on [date]. Consumer name: [name]. Address: [address]. Date: [date].</p></blockquote>" ],
        [ "Private sales", "There is no statutory withdrawal right between private individuals unless the seller offers one in the listing. PCMarket buyer protection still applies to the situations it covers." ],
        [ "Warranty", "New goods from professional sellers carry the statutory two-year warranty from delivery. For used goods the warranty may be reduced to at least one year." ],
        [ "Starting a return", "Open the order, choose \"Return or issue\" and state the reason. If you cannot agree, open a case within the inspection window. Keep the packaging and proof of postage." ],
        [ "Refunds", "Refunds are made to the original payment method once the goods are received or the return is evidenced." ]
      ]
    ),
    "buyer_protection" => LegalSeed.page(
      "Buyer protection",
      "PCMarket buyer protection is designed to make second-hand technology purchases safer. These are the main rules.",
      [
        [ "What is covered", [
          "Payments made entirely inside PCMarket.",
          "Orders not received or seriously damaged.",
          "Items materially different from the listing.",
          "Counterfeits and undisclosed defects.",
          "Issues reported within the inspection window."
        ] ],
        [ "What is not covered", [
          "Off-platform payments, including direct transfers.",
          "Damage caused by misuse after receipt.",
          "Subjective disagreements not stated in the listing.",
          "Transactions contrary to these terms or the law."
        ] ],
        [ "Inspection window", "After delivery you have a configurable window (usually 2 days) to inspect the item and confirm receipt or open a case. Without action, the order completes automatically and the seller is paid." ],
        [ "Opening a case", "Open the order, select \"Open dispute\", choose a reason and attach photos. The seller may respond. If you cannot agree, our team reviews the evidence and may order a full or partial refund." ],
        [ "Timing", "Cases are handled in order of arrival. Refunds may take several business days depending on your bank." ],
        [ "Contact", "Questions before buying: {{support_email}} or the help centre." ]
      ]
    ),
    "seller_terms" => LegalSeed.page(
      "Seller terms",
      "These terms apply to anyone listing or selling on PCMarket, whether private or professional.",
      [
        [ "General obligations", [
          "Describe the item, condition and price accurately and completely.",
          "Have the right to sell the item and ensure it is lawful.",
          "Reply to messages and ship on time.",
          "Pack safely and provide tracking where possible.",
          "Comply with tax, consumer and data protection rules."
        ] ],
        [ "Private and professional sellers", "You must state whether you sell privately or professionally. Professionals must provide their company name, tax number and contact details, give the required pre-contractual information and honour statutory warranties. Private sellers may not present themselves as a business or issue invoices that do not belong to them." ],
        [ "Prohibited practices", [
          "Listing stolen, counterfeit or recalled items.",
          "Manipulating photos, descriptions or reviews.",
          "Requesting off-platform payments to bypass buyer protection.",
          "Creating multiple accounts to evade suspension."
        ] ],
        [ "Fees and payouts", "Use is currently free, apart from featured services. We may introduce commissions with at least 30 days' notice. Payouts are released after receipt is confirmed or the inspection window ends, less commission and agreed shipping." ],
        [ "DAC7 and tax data", "As a digital platform, PCMarket must collect certain tax data and report sellers exceeding 30 sales or EUR 2,000 per calendar year to the German Federal Central Tax Office (BZSt) under the Platform Tax Transparency Act (PStTG). Without the required data we may restrict selling." ],
        [ "Suspension", "We may suspend or close accounts for serious breaches, repeated issues or legal requirements. Amounts owed for confirmed orders are settled under these terms and the law." ]
      ]
    ),
    "prohibited_items" => LegalSeed.page(
      "Prohibited items",
      "To protect the community and comply with the law, certain items may not be listed on PCMarket. This list is indicative.",
      [
        [ "Stolen or unlawfully obtained items", "Stolen, misappropriated or fraudulently obtained items, or items without provable origin, are prohibited. We may remove listings and inform authorities." ],
        [ "Counterfeits", "Counterfeit products, replicas presented as genuine and items infringing intellectual property are prohibited." ],
        [ "Recalled or unsafe products", "Products subject to official recall, safety alerts or safety breaches are prohibited." ],
        [ "Locked devices", "Phones, tablets and computers with locked accounts, remote activation, iCloud, Google or corporate accounts preventing normal use are not allowed. Sellers must unlink all accounts before shipping." ],
        [ "Weapons and regulated items", "Firearms, ammunition, prohibited knives, explosives, fireworks, tear gas and other items requiring authorisation are prohibited." ],
        [ "Dangerous or illegal products", "Drugs, medicines, hazardous chemicals, radioactive materials, organs, protected species, identity documents, third-party personal data and malware are prohibited." ],
        [ "Services and content", "Illegal services, adult content, gambling, abusive lending, cryptocurrencies and pyramid schemes are prohibited." ],
        [ "Consequences", "We may remove listings, suspend accounts and inform authorities. If unsure, contact {{support_email}} before listing." ]
      ]
    ),
    "dsa_contact" => LegalSeed.page(
      "DSA contact and illegal content reports",
      "PCMarket complies with Regulation (EU) 2022/2065 on Digital Services (DSA). This page explains how to contact us and report illegal content.",
      [
        [ "Point of contact", "The central contact point for authorities, users and third parties is {{legal_email}}. For support and consumer questions: {{support_email}}. We reply in the language of the communication or, failing that, in Spanish or English." ],
        [ "Reporting content", "Anyone may report a listing, message or profile they consider illegal. Include the link or identifier, the reason, sufficient explanation and evidence where possible. Manifestly unfounded or abusive reports may be dismissed." ],
        [ "Handling", "We review reports without undue delay, take proportionate measures and inform you of the decision. If content is removed, the affected user receives a clear statement of reasons and may appeal." ],
        [ "Internal complaints", "Users may challenge moderation, suspension or removal decisions via the contact form or {{legal_email}}. A free internal complaint system is available for at least six months." ],
        [ "Out-of-court dispute resolution", "You may use an accredited consumer arbitration body. PCMarket is not obliged and generally not willing to participate in consumer arbitration under the German VSBG; statutory rights remain unaffected. The EU online dispute resolution platform was discontinued in July 2025." ],
        [ "Transparency", "We publish aggregated moderation information where required by law. Relevant automated decisions are reviewed by a person where they affect user rights." ],
        [ "Postal address", "{{company_legal_name}}, {{company_address}}. Mark formal notices \"DSA\"." ]
      ]
    )
  }
}.freeze
